/* eslint-disable @typescript-eslint/consistent-type-imports -- Setup file uses dynamic imports where typeof requires value imports */
import { vi } from "vitest";

vi.mock("undici", async (importOriginal) => {
	return {
		...(await importOriginal<typeof import("undici")>()),
		/**
		 * Why do we have this hacky mock?
		 *
		 * MSW intercepts requests made via globalThis.fetch but not undici.fetch.
		 * Since workers-auth imports fetch, Request, and Response from undici,
		 * we need to replace them with their global equivalents so MSW can
		 * intercept and properly handle requests.
		 *
		 * We use getters so that we always get the up-to-date mocked versions
		 * that MSW provides.
		 */
		get fetch() {
			return globalThis.fetch;
		},
		get FormData() {
			return globalThis.FormData;
		},
		get Headers() {
			return globalThis.Headers;
		},
		get Request() {
			return globalThis.Request;
		},
		get Response() {
			return globalThis.Response;
		},
	};
});

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { getGlobalConfigPath, UserError } from "@cloudflare/workers-utils";
import { runInTempDir } from "@cloudflare/workers-utils/test-helpers";
import { afterEach, beforeEach, describe, it } from "vitest";
import {
	findKeyringBinding,
	getKeyringInstallDir,
	installKeyringBindingSync,
	PINNED_KEYRING_VERSION,
	resolveKeyringEntryFactory,
	setNpmRunner,
} from "../../../src/credential-store/key-providers/lazy-installer";
import type { SpawnSyncReturns } from "node:child_process";

function mockResult({
	status = 0,
	stdout = "",
	stderr = "",
}: {
	status?: number | null;
	stdout?: string;
	stderr?: string;
} = {}): SpawnSyncReturns<string> {
	return {
		status,
		stdout,
		stderr,
		signal: null,
		output: [null, stdout, stderr],
		pid: 1,
	} as SpawnSyncReturns<string>;
}

// The keyring binding install dir is derived from the consumer-provided global
// config path (resolved fresh per call so the runInTempDir HOME stub applies).
const installDir = () => getKeyringInstallDir(getGlobalConfigPath());

describe("lazy keyring installer", () => {
	runInTempDir();
	let lastInvocation: string[] | undefined;

	beforeEach(() => {
		lastInvocation = undefined;
	});

	afterEach(() => {
		setNpmRunner(undefined);
	});

	describe("findKeyringBinding", () => {
		it("returns null when neither the lazy dir nor the global root has the binding", ({
			expect,
		}) => {
			setNpmRunner((args) => {
				lastInvocation = args;
				return mockResult({ stdout: "/nonexistent/global/root\n" });
			});
			expect(findKeyringBinding(installDir())).toBeNull();
			expect(lastInvocation).toEqual(["root", "-g"]);
		});

		it("returns the lazy install path when the binding lives there", ({
			expect,
		}) => {
			const dir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			mkdirSync(dir, { recursive: true });
			writeFileSync(path.join(dir, "index.js"), "module.exports = {};");
			expect(findKeyringBinding(installDir())).toBe(dir);
		});

		it("falls back to the global npm root when the lazy dir is empty", ({
			expect,
		}) => {
			const globalRoot = path.join(getGlobalConfigPath(), "global-npm-root");
			const bindingDir = path.join(globalRoot, "@napi-rs", "keyring");
			mkdirSync(bindingDir, { recursive: true });
			writeFileSync(path.join(bindingDir, "index.js"), "module.exports = {};");
			setNpmRunner(() => mockResult({ stdout: globalRoot + "\n" }));
			expect(findKeyringBinding(installDir())).toBe(bindingDir);
		});

		it("returns null when `npm root -g` throws (npm not on PATH)", ({
			expect,
		}) => {
			setNpmRunner(() => {
				throw new Error("spawn npm ENOENT");
			});
			expect(findKeyringBinding(installDir())).toBeNull();
		});

		it("returns null when `npm root -g` exits non-zero", ({ expect }) => {
			setNpmRunner(() => mockResult({ status: 1 }));
			expect(findKeyringBinding(installDir())).toBeNull();
		});

		it("treats a binding whose native binary is missing as absent", ({
			expect,
		}) => {
			// Regression: an interrupted `npm install` can leave `index.js` on
			// disk without the platform-specific `.node` binary it requires.
			// Trusting `index.js` alone reported that wreck as "available"
			// forever — the install was never retried and every credential
			// read threw a raw module-resolution error instead.
			const dir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			mkdirSync(dir, { recursive: true });
			writeFileSync(
				path.join(dir, "index.js"),
				// Exactly what the real binding does, minus the binary.
				'require("./keyring.win32-x64-msvc.node");'
			);
			setNpmRunner((args) => {
				lastInvocation = args;
				return mockResult({ stdout: "/nonexistent/global/root\n" });
			});

			expect(findKeyringBinding(installDir())).toBeNull();
			// Having rejected the local wreck, it still probes the global root.
			expect(lastInvocation).toEqual(["root", "-g"]);
		});

		it("ignores a global binding that cannot be loaded", ({ expect }) => {
			const globalRoot = path.join(getGlobalConfigPath(), "global-npm-root");
			const bindingDir = path.join(globalRoot, "@napi-rs", "keyring");
			mkdirSync(bindingDir, { recursive: true });
			writeFileSync(
				path.join(bindingDir, "index.js"),
				'require("./keyring.win32-x64-msvc.node");'
			);
			setNpmRunner(() => mockResult({ stdout: globalRoot + "\n" }));
			expect(findKeyringBinding(installDir())).toBeNull();
		});

		it("recovers when a reinstall repairs a half-installed binding", ({
			expect,
		}) => {
			// The end-to-end recovery this is all for: a broken install must be
			// reported absent (so the resolver reinstalls), and the repaired
			// install must then be picked up.
			const dir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			mkdirSync(dir, { recursive: true });
			writeFileSync(
				path.join(dir, "index.js"),
				'require("./keyring.win32-x64-msvc.node");'
			);
			setNpmRunner((args) => {
				if (args[0] === "root") {
					return mockResult({ stdout: "/nonexistent/global/root\n" });
				}
				writeFileSync(path.join(dir, "index.js"), "module.exports = {};");
				return mockResult({});
			});

			expect(findKeyringBinding(installDir())).toBeNull();
			installKeyringBindingSync(installDir());
			expect(findKeyringBinding(installDir())).toBe(dir);
		});

		it("memoizes the result so repeated calls do not re-spawn npm", ({
			expect,
		}) => {
			// Without memoization the resolver's per-credential-op resolution
			// would spawn `npm root -g` on every read/write. We probe at most
			// once per process for the missing-binding case.
			let spawnCount = 0;
			setNpmRunner((args) => {
				spawnCount += 1;
				lastInvocation = args;
				return mockResult({ stdout: "/nonexistent/global/root\n" });
			});
			expect(findKeyringBinding(installDir())).toBeNull();
			expect(findKeyringBinding(installDir())).toBeNull();
			expect(findKeyringBinding(installDir())).toBeNull();
			expect(spawnCount).toBe(1);
		});
	});

	describe("installKeyringBindingSync", () => {
		it("creates a private host package.json before invoking npm install", ({
			expect,
		}) => {
			const bindingDir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			setNpmRunner((args) => {
				lastInvocation = args;
				// The install verifies its own work, so the runner has to
				// actually land a loadable binding to count as a success.
				mkdirSync(bindingDir, { recursive: true });
				writeFileSync(
					path.join(bindingDir, "index.js"),
					"module.exports = {};"
				);
				return mockResult({});
			});
			installKeyringBindingSync(installDir());
			const hostPkgJson = path.join(installDir(), "package.json");
			expect(existsSync(hostPkgJson)).toBe(true);
			expect(lastInvocation).toEqual([
				"install",
				`@napi-rs/keyring@${PINNED_KEYRING_VERSION}`,
				"--prefix",
				installDir(),
				"--no-save",
				"--no-audit",
				"--no-fund",
				"--no-package-lock",
				"--loglevel=error",
			]);
		});

		it("throws a UserError with the npm stderr on non-zero exit", ({
			expect,
		}) => {
			setNpmRunner(() => mockResult({ status: 1, stderr: "404 not found" }));
			expect(() => installKeyringBindingSync(installDir())).toThrow(
				/Failed to install `@napi-rs\/keyring` \(npm exited 1\)[\s\S]*404 not found/
			);
		});

		it("throws a UserError when the npm spawn itself fails (npm not on PATH)", ({
			expect,
		}) => {
			setNpmRunner(() => {
				throw new Error("spawn npm ENOENT");
			});
			expect(() => installKeyringBindingSync(installDir())).toThrow(
				/Failed to spawn `npm` to install the keyring backend/
			);
		});

		it("throws a UserError when npm exits 0 without leaving a loadable binding", ({
			expect,
		}) => {
			// npm exits 0 when an optional dependency cannot be fetched, and
			// the platform-specific `.node` binary is exactly that. Reporting
			// success here would leave the resolver on its `needs-install`
			// branch — which only latches its session failure flag when the
			// install throws — so the whole install would be respawned on
			// every single credential read and write.
			const bindingDir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			setNpmRunner((args) => {
				if (args[0] === "root") {
					return mockResult({ stdout: "/nonexistent/global/root\n" });
				}
				mkdirSync(bindingDir, { recursive: true });
				writeFileSync(
					path.join(bindingDir, "index.js"),
					'require("./keyring.win32-x64-msvc.node");'
				);
				return mockResult({});
			});

			// A `UserError` specifically: the resolver reports it verbatim when
			// keyring storage was forced via `CLOUDFLARE_AUTH_USE_KEYRING`.
			expect(() => installKeyringBindingSync(installDir())).toThrow(UserError);
			expect(() => installKeyringBindingSync(installDir())).toThrow(
				/`npm` reported success but the `@napi-rs\/keyring` native binding still cannot be loaded[\s\S]*npm install -g @napi-rs\/keyring@\d+\.\d+\.\d+/
			);
		});

		it("does not overwrite an existing host package.json", ({ expect }) => {
			const dir = installDir();
			mkdirSync(dir, { recursive: true });
			const hostPkgJson = path.join(dir, "package.json");
			writeFileSync(hostPkgJson, '{"customMarker":true}');

			const bindingDir = path.join(dir, "node_modules", "@napi-rs", "keyring");
			setNpmRunner(() => {
				mkdirSync(bindingDir, { recursive: true });
				writeFileSync(
					path.join(bindingDir, "index.js"),
					"module.exports = {};"
				);
				return mockResult({});
			});
			installKeyringBindingSync(installDir());
			expect(readFileSync(hostPkgJson, "utf-8")).toContain("customMarker");
		});

		it("invalidates the findKeyringBinding cache so a fresh install is picked up", ({
			expect,
		}) => {
			// Regression: `findKeyringBinding()` memoizes its result. The
			// install path must clear the cached "not found" entry so the
			// next resolution sees the freshly-installed binding instead of
			// reporting it as missing forever.
			const bindingDir = path.join(
				installDir(),
				"node_modules",
				"@napi-rs",
				"keyring"
			);
			let installCalled = false;
			setNpmRunner((args) => {
				if (args[0] === "root") {
					return mockResult({ stdout: "/nonexistent/global/root\n" });
				}
				// `install` arm: write the binding files in place so the
				// next `findKeyringBinding()` call discovers them.
				installCalled = true;
				mkdirSync(bindingDir, { recursive: true });
				writeFileSync(
					path.join(bindingDir, "index.js"),
					"module.exports = {};"
				);
				return mockResult({});
			});

			// First lookup populates the cache with `null`.
			expect(findKeyringBinding(installDir())).toBeNull();

			// Install lands the binding on disk and invalidates the cache.
			installKeyringBindingSync(installDir());
			expect(installCalled).toBe(true);

			// Next lookup must re-check the filesystem and return the new
			// binding path (not the cached `null`).
			expect(findKeyringBinding(installDir())).toBe(bindingDir);
		});
	});

	describe("resolveKeyringEntryFactory", () => {
		it("throws a UserError with remediation when no binding is available", ({
			expect,
		}) => {
			// Callers resolve availability before getting here, so this is
			// close to an internal invariant violation — but it is still the
			// user's machine that needs fixing, so it must not surface as a
			// bare module-resolution stack trace.
			setNpmRunner(() => mockResult({ stdout: "/nonexistent/global/root\n" }));
			expect(() => resolveKeyringEntryFactory(installDir())).toThrow(UserError);
			expect(() => resolveKeyringEntryFactory(installDir())).toThrow(
				/native binding is not available[\s\S]*npm install -g @napi-rs\/keyring@\d+\.\d+\.\d+/
			);
		});
	});
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { removeDirSync } from "@cloudflare/workers-utils";
import { afterEach, beforeEach, describe, test, vi } from "vitest";
import {
	ensureBrowserInstalled,
	isInstallMarkedComplete,
} from "../../../src/plugins/browser-rendering/install";

const BUILD_ID = "126.0.6478.182";
const PLATFORM = "linux64";

let cacheDir: string;

vi.mock(
	"@cloudflare/workers-utils/global-wrangler-config-path",
	async (importOriginal) => ({
		...(await importOriginal<
			typeof import("@cloudflare/workers-utils/global-wrangler-config-path")
		>()),
		// Keep the real filesystem helper; only the cache location is faked.
		getGlobalWranglerCachePath: () => cacheDir,
	})
);

const install = vi.hoisted(() => vi.fn());

vi.mock("@puppeteer/browsers", () => ({
	Browser: { CHROME: "chrome" },
	detectBrowserPlatform: () => PLATFORM,
	resolveBuildId: (_browser: string, _platform: string, version: string) =>
		Promise.resolve(version),
	install,
}));

const log = {
	warn: vi.fn(),
	debug: vi.fn(),
};

/** The directory `ensureBrowserInstalled` should resolve to. */
function installDirFor(): string {
	return path.join(cacheDir, "chrome", `${PLATFORM}-${BUILD_ID}`);
}

/** Take a handle on the install, as a session about to launch Chrome would. */
function acquireInstall() {
	return ensureBrowserInstalled({ browserVersion: BUILD_ID, log });
}

/** Make `install()` behave like a real extraction into the cache. */
function stubSuccessfulInstall(): void {
	install.mockImplementation(async () => {
		const installDir = installDirFor();
		await fs.promises.mkdir(installDir, { recursive: true });
		await fs.promises.writeFile(path.join(installDir, "chrome"), "");
		return { executablePath: path.join(installDir, "chrome") };
	});
}

beforeEach(() => {
	cacheDir = fs.mkdtempSync(path.join(os.tmpdir(), "miniflare-chrome-"));
	install.mockReset();
	log.warn.mockReset();
	log.debug.mockReset();
});

afterEach(() => {
	removeDirSync(cacheDir);
});

describe("ensureBrowserInstalled", () => {
	test("resolves the versioned install directory", async ({ expect }) => {
		stubSuccessfulInstall();

		const { installDir, executablePath } = await acquireInstall();

		expect(installDir).toBe(installDirFor());
		expect(executablePath).toBe(path.join(installDirFor(), "chrome"));
	});

	test("shares a single install between concurrent callers", async ({
		expect,
	}) => {
		// Without the in-flight map, the second caller reaches `install()` while
		// the first is still extracting. `@puppeteer/browsers` then short-circuits
		// on the partially-written directory and hands back a Chrome that cannot
		// launch — the failure this map exists to prevent.
		install.mockImplementation(async () => {
			// Long enough to still be extracting when the second call arrives.
			await new Promise((resolve) => setTimeout(resolve, 50));
			const installDir = installDirFor();
			await fs.promises.mkdir(installDir, { recursive: true });
			return { executablePath: path.join(installDir, "chrome") };
		});

		const [first, second] = await Promise.all([
			acquireInstall(),
			acquireInstall(),
		]);

		expect(first.executablePath).toBe(second.executablePath);
		expect(install).toHaveBeenCalledTimes(1);
	});

	test("allows a fresh install once the previous one has settled", async ({
		expect,
	}) => {
		stubSuccessfulInstall();

		await acquireInstall();
		await acquireInstall();

		expect(install).toHaveBeenCalledTimes(2);
	});

	test("does not mark the install as verified", async ({ expect }) => {
		// `install()` resolving proves nothing: it short-circuits whenever the
		// directory and executable exist, which a half-extracted archive
		// satisfies. Marking here would suppress the recovery in `discard()`.
		stubSuccessfulInstall();

		const { installDir } = await acquireInstall();

		expect(isInstallMarkedComplete(installDir)).toBe(false);
	});
});

describe("markVerified", () => {
	test("marks the install, idempotently", async ({ expect }) => {
		stubSuccessfulInstall();
		const installed = await acquireInstall();

		expect(isInstallMarkedComplete(installed.installDir)).toBe(false);
		await installed.markVerified();
		expect(isInstallMarkedComplete(installed.installDir)).toBe(true);
		await installed.markVerified();
		expect(isInstallMarkedComplete(installed.installDir)).toBe(true);
	});

	test("does not throw when the install directory is gone", async ({
		expect,
	}) => {
		// Resolve an install without creating anything on disk, as if the
		// directory had been swept up between installing and launching.
		install.mockResolvedValue({
			executablePath: path.join(installDirFor(), "chrome"),
		});
		const installed = await acquireInstall();

		await installed.markVerified();

		expect(isInstallMarkedComplete(installed.installDir)).toBe(false);
		expect(log.debug).toHaveBeenCalled();
	});
});

describe("discard", () => {
	test("clears an unverified install", async ({ expect }) => {
		stubSuccessfulInstall();
		const installed = await acquireInstall();

		expect(await installed.discard()).toEqual({ outcome: "cleared" });
		expect(fs.existsSync(installed.installDir)).toBe(false);
		expect(log.warn).toHaveBeenCalled();
	});

	test("keeps an install that Chrome has already launched from", async ({
		expect,
	}) => {
		// A launch failure here is a real bug, not a bad download, so deleting
		// 150 MB and trying again would only hide it.
		stubSuccessfulInstall();
		const installed = await acquireInstall();
		await installed.markVerified();

		expect(await installed.discard()).toEqual({ outcome: "verified" });
		expect(fs.existsSync(installed.installDir)).toBe(true);
		expect(log.warn).not.toHaveBeenCalled();
	});

	test("keeps an install a concurrent launch is still confirming", async ({
		expect,
	}) => {
		// Launches run concurrently, one per session acquire. If one succeeds
		// while another is failing, the failing one must not delete the
		// directory the working Chrome is running from — even though the on-disk
		// marker has not been written yet.
		stubSuccessfulInstall();
		const succeeding = await acquireInstall();
		const failing = await acquireInstall();

		// Deliberately not awaited: the marker write is still in flight.
		const marking = succeeding.markVerified();

		expect(await failing.discard()).toEqual({ outcome: "verified" });
		expect(fs.existsSync(failing.installDir)).toBe(true);

		await marking;
	});

	test("keeps an install a concurrent launch has already replaced", async ({
		expect,
	}) => {
		// Two launches failing against the same bad install: the first clears
		// and re-downloads it, and the second must retry against that fresh
		// copy rather than delete it too.
		stubSuccessfulInstall();
		const first = await acquireInstall();
		const second = await acquireInstall();

		expect(await first.discard()).toEqual({ outcome: "cleared" });

		// Stand in for the peer's re-download.
		await acquireInstall();

		expect(await second.discard()).toEqual({ outcome: "superseded" });
		expect(fs.existsSync(path.join(second.installDir, "chrome"))).toBe(true);
	});

	test("retries against a replacement the peer has already proven", async ({
		expect,
	}) => {
		// The peer got all the way through: cleared, re-downloaded, launched and
		// marked verified. The launch still holding the old generation must be
		// told to retry, not that the install is fine — otherwise it fails while
		// a working Chrome is available.
		stubSuccessfulInstall();
		const peer = await acquireInstall();
		const stale = await acquireInstall();

		await peer.discard();
		await (await acquireInstall()).markVerified();

		expect(await stale.discard()).toEqual({ outcome: "superseded" });
	});

	test("reports why an install could not be cleared", async ({ expect }) => {
		// Windows keeps handles on a just-crashed Chrome, so removal can fail.
		// The caller turns this into an actionable error, which matters because
		// Miniflare logs to a no-op by default.
		stubSuccessfulInstall();
		const installed = await acquireInstall();
		const locked = new Error("EBUSY: resource busy or locked");
		vi.spyOn(fs.promises, "rm").mockRejectedValue(locked);

		expect(await installed.discard()).toEqual({
			outcome: "cleanup-failed",
			cause: locked,
		});
	}, 20_000);
});

{
	"name": "@fixture/worker-email",
	"private": true,
	"scripts": {
		"deploy": "wrangler deploy",
		"start": "wrangler dev"
